// Author: MiYu. Minimal continuation checks required before building gameplay on retained native stacks.
#include "jass_runtime.h"
#include <windows.h>
#include <algorithm>
#include <bit>
#include <iostream>
#include <cstring>
#include <map>
#include <thread>

using namespace war3::jass;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
Module compile(std::string text){return Module::compile(Program::parse({{"threads.j",std::move(text),"authored thread check"}}));}
void bindWait(Runtime& r){r.bind("Yield",[](auto& vm,auto a){vm.sleep(std::bit_cast<float>(a[0].bits));return vm.nothing();});}
template<class F>void rejects(F run,std::string_view part){try{run();}catch(const std::exception& e){require(std::string_view(e.what()).find(part)!=std::string_view::npos,"Unexpected thread diagnostic");return;}throw std::runtime_error("Invalid thread operation succeeded");}
const char* waitNative="native Yield takes real seconds returns nothing\n";
}
int wmain(int argc,wchar_t** argv){
    unsigned passed=0,failed=0;auto test=[&](const char* name,auto run){if(argc>1 && std::none_of(argv+1,argv+argc,[&](const wchar_t* value){return std::wstring(value)==std::wstring(name,name+std::strlen(name));}))return;try{run();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cout<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
    test("locals_arrays_and_return_stack",[]{Runtime r(compile(std::string(waitNative)+"globals\ninteger result=0\nendglobals\nfunction sub takes integer n returns integer\nlocal integer array values\nset values[2]=n\ncall Yield(0.125)\nreturn values[2]+1\nendfunction\nfunction root takes nothing returns nothing\nlocal integer n=7\nset result=sub(n)\nendfunction\n"));bindWait(r);r.initialize();r.start("root");require(r.global("result").bits==0 && r.threadCount()==1,"Wait did not suspend entry");r.advanceThreads(.09375);require(r.global("result").bits==0,"Thread woke early");r.advanceThreads(.125);require(r.global("result").bits==8 && !r.threadCount(),"Local array or call return was lost");});
    test("native_stack_and_cooperative_cancellation",[]{int live=0,destroyed=0,after=0;Runtime r(compile(std::string(waitNative)+"native Bridge takes code action returns nothing\nfunction child takes nothing returns nothing\ncall Yield(0.03125)\nendfunction\nfunction root takes nothing returns nothing\ncall Bridge(function child)\nendfunction\n"));bindWait(r);r.bind("Bridge",[&](auto& vm,auto args){++live;struct Guard{int& live;int& destroyed;~Guard(){--live;++destroyed;}}guard{live,destroyed};vm.invoke(args[0]);++after;return vm.nothing();});r.initialize();r.start("root");require(live==1 && !destroyed,"Native stack was discarded");r.advanceThreads(2./32);require(!live && destroyed==1 && after==1,"Native continuation did not return");r.start("root");r.cancelThreads();require(!live && destroyed==2 && after==1 && !r.threadCount(),"Cancellation did not unwind native resources");});
    test("due_order_and_shared_globals",[]{Runtime r(compile(std::string(waitNative)+"globals\ninteger trace=0\nendglobals\nfunction a takes nothing returns nothing\nset trace=trace*10+1\ncall Yield(0.0625)\nset trace=trace*10+2\nendfunction\nfunction b takes nothing returns nothing\nset trace=trace*10+3\ncall Yield(0.03125)\nset trace=trace*10+4\nendfunction\n"));bindWait(r);r.initialize();r.start("a");r.start("b");require(r.global("trace").bits==13,"Independent entry did not run before wait");r.advanceThreads(1./32);require(r.global("trace").bits==13,"Real-valued wait was rounded down to an earlier tick");r.advanceThreads(2./32);require(r.global("trace").bits==1342 && !r.threadCount(),"Shared global ordering differs");});
    test("join_preserves_parent_native_call",[]{Runtime r(compile(std::string(waitNative)+"native Join takes code action returns nothing\nglobals\ninteger trace=0\nendglobals\nfunction child takes nothing returns nothing\nset trace=2\ncall Yield(0.125)\nset trace=3\nendfunction\nfunction parent takes nothing returns nothing\nset trace=1\ncall Join(function child)\nset trace=4\nendfunction\n"));bindWait(r);r.bind("Join",[](auto& vm,auto args){auto child=vm.start(args[0]);vm.waitThread(child);return vm.nothing();});r.initialize();r.start("parent");require(r.global("trace").bits==2 && r.threadCount()==2,"Parent did not wait for sleeping child");r.advanceThreads(.125);require(r.global("trace").bits==4 && !r.threadCount(),"Joined parent did not resume after child");});
    test("context_switch_hooks_isolate_entries",[]{Runtime r(compile(std::string(waitNative)+"native Context takes integer value returns nothing\nnative Read takes nothing returns integer\nglobals\ninteger a=0\ninteger b=0\nendglobals\nfunction first takes nothing returns nothing\ncall Context(7)\ncall Yield(0.0625)\nset a=Read()\nendfunction\nfunction second takes nothing returns nothing\ncall Context(42)\ncall Yield(0.03125)\nset b=Read()\nendfunction\n"));int context=123;std::map<ThreadId,int> contexts{{0,123}};r.threadHooks({[&](ThreadId id,ThreadId){contexts[id]=context;},[&](ThreadId from,ThreadId to){contexts.at(from)=context;context=contexts.at(to);},[&](ThreadId id){contexts.erase(id);}});bindWait(r);r.bind("Context",[&](auto& vm,auto args){context=int(args[0].bits);return vm.nothing();});r.bind("Read",[&](auto& vm,auto){return vm.integer(context);});r.initialize();r.start("first");r.start("second");require(context==123,"Suspended entry contaminated caller context");r.advanceThreads(.0625);require(r.global("a").bits==7 && r.global("b").bits==42 && context==123 && contexts.size()==1,"Thread context was not restored");});
    test("continuation_migrates_between_host_threads",[]{std::unique_ptr<Runtime> r;std::exception_ptr failure;std::thread worker([&]{try{r=std::make_unique<Runtime>(compile(std::string(waitNative)+"native Host takes nothing returns integer\nglobals\ninteger before=0\ninteger after=0\nendglobals\nfunction root takes nothing returns nothing\nset before=Host()\ncall Yield(0.125)\nset after=Host()\nendfunction\n"));bindWait(*r);r->bind("Host",[](auto& vm,auto){return vm.integer(std::bit_cast<std::int32_t>(GetCurrentThreadId()));});r->initialize();r->start("root");}catch(...){failure=std::current_exception();}});worker.join();if(failure)std::rethrow_exception(failure);auto old=r->global("before").bits;r->advanceThreads(.125);require(old!=GetCurrentThreadId() && r->global("after").bits==GetCurrentThreadId() && !r->threadCount(),"Sleeping stack did not migrate to its current owner");});
    test("yield_renews_budget_but_busy_loop_fails",[]{RuntimeLimits limits;limits.steps=80;Runtime r(compile(std::string(waitNative)+"globals\ninteger count=0\nendglobals\nfunction repeat takes nothing returns nothing\nloop\nexitwhen count>=50\nset count=count+1\ncall Yield(0.0)\nendloop\nendfunction\nfunction spin takes nothing returns nothing\nloop\nendloop\nendfunction\n"),limits);bindWait(r);r.initialize();r.start("repeat");for(unsigned i=1;i<=50;++i)r.advanceThreads(double(i)/32);require(r.global("count").bits==50 && !r.threadCount(),"Valid yielding loop exhausted its prior slice");rejects([&]{r.start("spin");},"instruction budget");require(!r.threadCount(),"Faulted thread retained its stack");});
    test("synchronous_condition_rejects_wait",[]{Runtime r(compile(std::string(waitNative)+"native Check takes code predicate returns boolean\nfunction predicate takes nothing returns boolean\ncall Yield(0.125)\nreturn true\nendfunction\nfunction root takes nothing returns nothing\nif Check(function predicate) then\nreturn\nendif\nendfunction\n"));bindWait(r);r.bind("Check",[](auto& vm,auto args){return vm.invokeNoYield(args[0]);});r.initialize();rejects([&]{r.start("root");},"synchronous condition");require(!r.threadCount(),"Condition failure leaked its thread");});
    test("thread_limit_and_reused_stack_reset",[]{RuntimeLimits limits;limits.threads=2;Runtime r(compile(std::string(waitNative)+"globals\ninteger count=0\nendglobals\nfunction wait takes nothing returns nothing\ncall Yield(1.0)\nendfunction\nfunction instant takes nothing returns nothing\nset count=count+1\nendfunction\n"),limits);bindWait(r);r.initialize();r.start("wait");r.start("wait");rejects([&]{r.start("wait");},"budget");r.cancelThreads();for(unsigned i=0;i<100;++i)r.start("instant");require(r.global("count").bits==100 && !r.threadCount(),"Recycled stack retained cancellation or task state");});
    test("runtime_destruction_unwinds_sleeping_native",[]{int live=0,finished=0;{Runtime r(compile(std::string(waitNative)+"native Scope takes code action returns nothing\nfunction child takes nothing returns nothing\ncall Yield(10.0)\nendfunction\nfunction root takes nothing returns nothing\ncall Scope(function child)\nendfunction\n"));bindWait(r);r.bind("Scope",[&](auto& vm,auto args){++live;struct Guard{int& value;~Guard(){--value;}}guard{live};vm.invoke(args[0]);++finished;return vm.nothing();});r.initialize();r.start("root");require(live==1,"Destruction check did not hold native resource");}require(!live && !finished,"Destruction skipped unwind or ran post-wait logic");});
    test("linked_vms_keep_globals_and_code_ownership",[]{std::string declarations=std::string(waitNative)+"native Store takes code callback returns nothing\n";std::string body="globals\ninteger value=0\nendglobals\nfunction action takes nothing returns nothing\ncall Yield(0.125)\nset value=value+1\nendfunction\nfunction save takes nothing returns nothing\ncall Store(function action)\nendfunction\n";Runtime map(compile(declarations+body)),ai(compile(declarations+body));Value callback;bindWait(map);map.bind("Store",[&](auto& vm,auto args){callback=args[0];return vm.nothing();});map.initialize();ai.inheritNatives(map);ai.shareThreads(map);ai.initialize();ai.invoke("save");map.start(callback);map.start("action");require(map.threadCount()==2 && ai.threadCount()==2,"Linked VMs did not share scheduler");map.advanceThreads(.125);require(map.global("value").bits==1 && ai.global("value").bits==1 && !ai.threadCount(),"Foreign callback used map globals or lost code ownership");ai.start("action");map.cancelThreads();require(map.global("value").bits==1 && ai.global("value").bits==1 && !map.threadCount(),"Linked cancellation ran suspended code");});
    test("paused_vm_isolation_and_remaining_wait",[]{std::string source=std::string(waitNative)+"globals\ninteger before=0\ninteger after=0\nendglobals\nfunction root takes nothing returns nothing\nset before=before+1\ncall Yield(0.125)\nset after=after+1\nendfunction\n";Runtime map(compile(source)),ai(compile(source));bindWait(map);map.initialize();ai.inheritNatives(map);ai.shareThreads(map);ai.initialize();map.start("root");ai.start("root");map.advanceThreads(.0625);ai.pauseThreads(true);map.advanceThreads(1);require(map.global("after").bits==1 && ai.global("after").bits==0,"AI pause froze map scripts or resumed AI");ai.start("root");require(ai.global("before").bits==1,"Paused creation ran its entry");ai.pauseThreads(false);map.advanceThreads(1);require(ai.global("before").bits==2 && ai.global("after").bits==0,"Queued AI did not start on resume");map.advanceThreads(1.03125);require(ai.global("after").bits==0,"Paused wait lost its remaining interval");map.advanceThreads(1.0625);require(ai.global("after").bits==1,"Resumed AI failed to retain its wait");map.cancelThreads();require(!map.threadCount() && ai.global("after").bits==1,"Paused/new thread cancellation resumed script code");});
    test("self_pause_and_deferred_creation",[]{Runtime r(compile("native Pause takes nothing returns nothing\nglobals\ninteger trace=0\nendglobals\nfunction root takes nothing returns nothing\nset trace=1\ncall Pause()\nset trace=trace*10+2\nendfunction\nfunction child takes nothing returns nothing\nset trace=trace*10+3\nendfunction\n"));r.bind("Pause",[](auto& vm,auto){vm.pauseThreads(true);return vm.nothing();});r.initialize();r.start("root");r.start("child");require(r.global("trace").bits==1 && r.threadCount()==2,"Self pause or deferred creation continued");r.pauseThreads(false);r.advanceThreads(0);require(r.global("trace").bits==123 && !r.threadCount(),"Paused instruction did not resume in stable order");r.start("root");r.start("child");r.cancelThreads();require(r.global("trace").bits==1 && !r.threadCount(),"Cancelling paused entries ran their continuation");});
    if(!passed && !failed){std::cerr<<"Unknown thread check selection\n";return 2;}if(GetModuleHandleW(L"Game.dll")){std::cout<<"FAIL Game.dll loaded\n";++failed;}std::cout<<"RESULT passed="<<passed<<" failed="<<failed<<'\n';return failed?1:0;
}
